<?php
declare(strict_types=1);require_once __DIR__.'/config/database.php'; require_once __DIR__.'/config/ui.php';$pdo=srnu_db();$tel=trim($_GET['telefono']??'');$q=trim($_GET['q']??'');$where=[];$p=[];if($tel!==''){$where[]='c.telefono=?';$p[]=$tel;}elseif($q!==''){$where[]='(c.cliente LIKE ? OR c.telefono LIKE ? OR c.vehiculo LIKE ? OR EXISTS(SELECT 1 FROM recepciones rr WHERE rr.cotizacion_id=c.id AND rr.placas LIKE ?))';$like='%'.$q.'%';$p=[$like,$like,$like,$like];}$sql="SELECT c.*, COALESCE((SELECT SUM(p.monto) FROM pagos p WHERE p.cotizacion_id=c.id),0) pagado, (SELECT COUNT(*) FROM garantias g WHERE g.cotizacion_id=c.id) garantias FROM cotizaciones c".($where?' WHERE '.implode(' AND ',$where):' WHERE 1=0').' ORDER BY c.fecha DESC,c.id DESC';$st=$pdo->prepare($sql);$st->execute($p);$rows=$st->fetchAll();function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="es"><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta charset="utf-8"><title>Historial cliente · SRNU</title><link rel="icon" href="favicon.png"><style>body{font-family:Arial;background:#f4f5f7}.w{max-width:1000px;margin:30px auto}.p{background:#fff;padding:16px;border-radius:10px;margin:12px 0}a,.btn{background:#111;color:#fff;padding:8px 11px;border-radius:7px;text-decoration:none;border:0}input{padding:9px;width:70%}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #eee;text-align:left}</style><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><?php srnu_appbar('cotizaciones'); ?><div class="w"><a href="cotizaciones.php">← Cotizaciones</a><h1>Historial de cliente / vehículo</h1><form class="p"><input name="q" value="<?=h($q)?>" placeholder="Nombre, teléfono o vehículo"><button class="btn">Buscar</button></form><div class="p"><table><tr><th>Fecha</th><th>Folio</th><th>Cliente</th><th>Vehículo</th><th>Estado</th><th>Total</th><th>Pagado</th><th>Garantías</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['fecha'])?></td><td><?=h($r['folio'])?></td><td><?=h($r['cliente'])?></td><td><?=h($r['vehiculo'])?></td><td><?=h($r['estado'])?></td><td>$<?=number_format((float)$r['total'],2)?></td><td>$<?=number_format((float)$r['pagado'],2)?></td><td><?= (int)$r['garantias'] ?></td><td><a href="cotizador.php?id=<?=(int)$r['id']?>">Abrir</a> <a href="pagos.php?id=<?=(int)$r['id']?>">Pagos</a> <a href="garantias.php?id=<?=(int)$r['id']?>">Garantías</a></td></tr><?php endforeach;?></table></div></div></body></html>
